+// Check if array is already sorted or reverse sorted
+static bool check_sorted(uint32_t* a, size_t n) {
+    if (n <= 1) return true;
+    bool asc = true, desc = true;
+    for (size_t i = 1; i < n; ++i) {
+        if (a[i] < a[i-1]) asc = false;
+        if (a[i] > a[i-1]) desc = false;
+        if (!asc && !desc) return false;
+    }
+    if (desc) {
+        size_t i = 0, j = n - 1;
+        while (i < j) {
+            uint32_t t = a[i]; a[i] = a[j]; a[j] = t;
+            ++i; --j;
+        }
+    }
+    return true;
+}
